using System.ComponentModel;
using System.Text.Json;

namespace ResearchAgent.Tools;

/// <summary>
/// Simulated web search tool that returns results for a query.
/// Replace the implementation with a real search API (e.g., Bing Search) for production use.
/// </summary>
public sealed class WebSearchTool
{
    private static readonly Dictionary<string, List<SearchResult>> SimulatedResults = new(StringComparer.OrdinalIgnoreCase)
    {
        ["quantum computing"] =
        [
            new("Quantum Computing Basics - MIT Technology Review",
                "Quantum computers use qubits that can exist in superposition, enabling them to process " +
                "exponentially more information than classical bits. Key players include IBM, Google, and " +
                "Microsoft. Google achieved quantum supremacy in 2019 with their Sycamore processor."),
            new("Applications of Quantum Computing - Nature",
                "Quantum computing promises breakthroughs in drug discovery, cryptography, optimization " +
                "problems, and materials science. Quantum simulation could model molecular interactions " +
                "that are intractable for classical computers."),
            new("Challenges in Quantum Computing - IEEE Spectrum",
                "Major challenges include qubit decoherence, error correction overhead, and the need for " +
                "extremely low operating temperatures. Current quantum computers are noisy intermediate-scale " +
                "quantum (NISQ) devices with limited practical utility."),
        ],
        ["artificial intelligence"] =
        [
            new("The State of AI in 2026 - Stanford HAI",
                "Large language models continue to advance with improved reasoning capabilities. " +
                "Multimodal AI systems can now process text, images, audio, and video. AI agents " +
                "are being deployed for complex multi-step tasks in enterprise settings."),
            new("AI Safety and Alignment - DeepMind Research",
                "Research into AI alignment focuses on ensuring AI systems act in accordance with " +
                "human values. Techniques include RLHF, constitutional AI, and interpretability research. " +
                "Regulatory frameworks are emerging globally."),
            new("AI in Healthcare - WHO Report",
                "AI-powered diagnostics show promise in radiology, pathology, and genomics. " +
                "FDA-approved AI medical devices have grown significantly. Challenges remain " +
                "in data privacy, bias mitigation, and clinical validation."),
        ],
    };

    [Description("Searches the web for information on a given query. Returns a list of relevant results with titles and snippets.")]
    public static string Search([Description("The search query string")] string query)
    {
        // Check for exact key matches first, then partial matches
        var results = SimulatedResults
            .Where(kvp => query.Contains(kvp.Key, StringComparison.OrdinalIgnoreCase)
                          || kvp.Key.Contains(query, StringComparison.OrdinalIgnoreCase))
            .SelectMany(kvp => kvp.Value)
            .ToList();

        if (results.Count == 0)
        {
            results =
            [
                new($"Search results for: {query}",
                    $"Found general information about '{query}'. This is a broad topic with " +
                    "applications across multiple domains. Further research is recommended " +
                    "to narrow down specific areas of interest."),
            ];
        }

        return JsonSerializer.Serialize(results, JsonSerializerOptions.Web);
    }

    private sealed record SearchResult(string Title, string Snippet);
}

using System.ComponentModel;
using System.Text;

namespace ResearchAgent.Tools;

/// <summary>
/// Tool for taking and reviewing research notes during an investigation.
/// </summary>
public sealed class NoteTool
{
    private readonly List<Note> _notes = [];

    [Description("Saves a research note with a category tag. Use this to record important findings during research.")]
    public string SaveNote(
        [Description("A short category for the note, e.g. 'key-finding', 'definition', 'challenge'")] string category,
        [Description("The content of the note")] string content)
    {
        var note = new Note(category, content, DateTime.UtcNow);
        _notes.Add(note);
        return $"Note #{_notes.Count} saved under '{category}'.";
    }

    [Description("Retrieves all saved research notes, optionally filtered by category.")]
    public string GetNotes(
        [Description("Optional category filter. Pass empty string to get all notes.")] string category = "")
    {
        var filtered = string.IsNullOrWhiteSpace(category)
            ? _notes
            : _notes.Where(n => n.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

        if (filtered.Count == 0)
        {
            return "No notes found.";
        }

        var sb = new StringBuilder();
        for (var i = 0; i < filtered.Count; i++)
        {
            var n = filtered[i];
            sb.AppendLine($"[{i + 1}] ({n.Category}) {n.Content}");
        }

        return sb.ToString();
    }

    private sealed record Note(string Category, string Content, DateTime Timestamp);
}

