using Microsoft.Agents.AI;
using Microsoft.Agents.AI.ChatCompletion;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using OpenAI;
using ResearchAgent.Tools;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// --- DI Setup ---
var services = new ServiceCollection();

services.AddLogging(b => b.AddConsole().SetMinimumLevel(LogLevel.Warning));

services.AddChatClient(builder =>
    builder.Use(new OpenAIClient(apiKey).GetChatClient(modelId).AsIChatClient()));

var sp = services.BuildServiceProvider();

// --- Tool Registration ---
var noteTool = new NoteTool();

var tools = new AIFunction[]
{
    AIFunctionFactory.Create(WebSearchTool.Search),
    AIFunctionFactory.Create(noteTool.SaveNote),
    AIFunctionFactory.Create(noteTool.GetNotes),
};

// --- Agent Setup ---
var chatClient = sp.GetRequiredService<IChatClient>();
var agent = new ChatClientAgent(chatClient, tools);

var systemPrompt = """
    You are a research assistant. Your job is to thoroughly research a topic the user provides.

    Follow this workflow:
    1. Search the web for information on the topic (perform multiple searches if needed).
    2. Save important findings as notes using the SaveNote tool with appropriate categories
       (e.g., "key-finding", "definition", "application", "challenge").
    3. After gathering enough information, retrieve all your notes with GetNotes.
    4. Provide a well-structured summary of your research findings to the user.

    Be thorough but concise. Always cite the source of information when available.
    """;

var options = new AgentInvokeOptions
{
    MaximumIterations = 10,
    Instructions = systemPrompt,
};

// --- Run ---
var topic = args.Length > 0 ? string.Join(' ', args) : "quantum computing";

Console.WriteLine($"🔍 Researching: {topic}\n");

var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
};

await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine();

